// Synthetic replica of react-native-webview@13 sources (TSX). Renders a native
// RNCWebView host component registered off the React Native default export.
import ReactNative from "react-native";

const RNCWebView =
  (ReactNative as { requireNativeComponent?: (name: string) => unknown }).requireNativeComponent?.(
    "RNCWebView",
  ) ?? "RNCWebView";

export const WEBVIEW_OK = "WEBVIEW_OK";

export type WebViewSource = { uri: string } | { html: string };

export function WebView(props: { source: WebViewSource; javaScriptEnabled?: boolean }) {
  return <RNCWebView source={props.source} javaScriptEnabled={props.javaScriptEnabled ?? true} />;
}

export default WebView;
